function getDailyAverageSeries(series = []) {
  if (!series.length) return [];

  const grouped = new Map();

  series.forEach((item) => {
    const existing = grouped.get(item.dateKey);

    if (existing) {
      existing.level += item.level;
      existing.count += 1;
      return;
    }

    grouped.set(item.dateKey, {
      ...item,
      count: 1,
      level: item.level,
    });
  });

  return Array.from(grouped.values())
    .map((item) => ({
      ...item,
      level: Number((item.level / item.count).toFixed(2)),
      label: `${formatShortDate(item.dateKey)} `,
    }))
    .sort((a, b) => a.dateKey.localeCompare(b.dateKey));
}

export function getSelectedPoint(pointsList = points, pointId = points[0]?.id) {
  const point = pointsList.find((point) => point.id === pointId) ?? pointsList[0];

  if (!point) return undefined;

  const series = point.id === "numae" ? getDailyAverageSeries(point.series) : point.series;

  return {
    ...point,
    series,
  };
}

export function formatShortDate(dateKey) {
  const [year, month, day] = dateKey.split("-");
  return `${day}/${month}`;
}

export function getDateLabel(dateKey) {
  const point = getSelectedPoint(points);
  return point.series.find((item) => item.dateKey === dateKey)?.label ?? dateKey;
}
